{
  "imports": [
    "from decimal import Decimal",
    "import pytest",
    "from ledger.installments import installments"
  ],
  "tests": [
    {
      "name": "test_installments_last_absorbs_remainder",
      "intent": "the example from the task: 100.00 into 3 instalments gives [33.33, 33.33, 33.34]",
      "code": "# intent: the example from the task: 100.00 into 3 instalments gives [33.33, 33.33, 33.34]\ndef test_installments_last_absorbs_remainder():\n    assert installments(Decimal(\"100.00\"), 3) == [Decimal(\"33.33\"), Decimal(\"33.33\"), Decimal(\"33.34\")]\n"
    },
    {
      "name": "test_installments_sum_equals_total",
      "intent": "instalments always add up to the total",
      "code": "# intent: instalments always add up to the total\ndef test_installments_sum_equals_total():\n    total = Decimal(\"123.45\")\n    count = 7\n    result = installments(total, count)\n    assert sum(result) == total\n"
    },
    {
      "name": "test_installments_all_but_last_rounded_down",
      "intent": "all instalments except the last are rounded down to cents",
      "code": "# intent: all instalments except the last are rounded down to cents\ndef test_installments_all_but_last_rounded_down():\n    result = installments(Decimal(\"100.00\"), 3)\n    assert result[0] == Decimal(\"33.33\")\n    assert result[1] == Decimal(\"33.33\")\n"
    },
    {
      "name": "test_installments_single_payment_is_total",
      "intent": "single instalment returns the total unchanged",
      "code": "# intent: single instalment returns the total unchanged\ndef test_installments_single_payment_is_total():\n    assert installments(Decimal(\"50.00\"), 1) == [Decimal(\"50.00\")]\n"
    },
    {
      "name": "test_installments_zero_count_raises",
      "intent": "zero count raises ValueError",
      "code": "# intent: zero count raises ValueError\ndef test_installments_zero_count_raises():\n    with pytest.raises(ValueError):\n        installments(Decimal(\"50.00\"), 0)\n"
    },
    {
      "name": "test_installments_negative_count_raises",
      "intent": "negative count raises ValueError",
      "code": "# intent: negative count raises ValueError\ndef test_installments_negative_count_raises():\n    with pytest.raises(ValueError):\n        installments(Decimal(\"50.00\"), -1)\n"
    }
  ]
